with feeders as (
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__MD_SEQ_NO))) as HUB_RISK_OBJECT_HK
        , MLC_RISK_CLASS as RISK_CLASS_CODE
        , cast(null as varchar) as RISK_OBJECT_DESCRIPTION
        , 'BA_HCP_PROD_8428_GPG_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8428_gpg_loader') }}
    where (nullif(trim(MD_SEQ_NO),'')) is not null
),

resolved as (
    select
        HUB_RISK_OBJECT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RISK_CLASS_CODE end) as RISK_CLASS_CODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RISK_OBJECT_DESCRIPTION end) as RISK_OBJECT_DESCRIPTION,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_RISK_OBJECT_HK
),

hashed as (
    select
        *,
        case when RISK_CLASS_CODE is not null or RISK_OBJECT_DESCRIPTION is not null
                     then md5(upper(coalesce(cast(RISK_CLASS_CODE as varchar), '') || '|' || coalesce(cast(RISK_OBJECT_DESCRIPTION as varchar), '')))
                end as SAT_RISK_OBJECT_CORE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_RISK_OBJECT_HK is not null
  and SAT_RISK_OBJECT_CORE_HASHDIFF is not null
